const body = $input.first().json.body ?? $input.first().json;
const url = (body.url ?? '').toString().trim();
let videoId = body.video_id;
if (!videoId) {
  const m = url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/shorts\/)([A-Za-z0-9_-]{6,})/);
  if (!m) throw new Error('invalid_youtube_url');
  videoId = m[1];
}
return [{ json: { url, video_id: videoId } }];

// Convert ISO 8601 duration (PT24M18S) → seconds.
function iso8601ToSec(s) {
  const m = (s || '').match(/^PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/);
  if (!m) return 0;
  return (+m[1] || 0) * 3600 + (+m[2] || 0) * 60 + (+m[3] || 0);
}
const resp = $input.first().json;
const item = resp.items?.[0];
if (!item) throw new Error('video_not_found');
const snippet = item.snippet ?? {};
const content = item.contentDetails ?? {};
const stats = item.statistics ?? {};
return [{
  json: {
    video_id: item.id,
    title: snippet.title,
    channel: snippet.channelTitle,
    duration_seconds: iso8601ToSec(content.duration),
    thumbnail_url: snippet.thumbnails?.maxres?.url ?? snippet.thumbnails?.high?.url ?? snippet.thumbnails?.default?.url,
    view_count: stats.viewCount ? parseInt(stats.viewCount, 10) : null,
    published_at: snippet.publishedAt ?? null,
  },
}];
